d><td class="text-end"><a class="action-button edit" href="<?php echo e(route('admin.orders.show',$order)); ?>"><i class="bi bi-eye me-1"></i>Details</a></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="8" class="text-center py-5 text-muted"><i class="bi bi-cart-x fs-2 d-block mb-2"></i>No ecommerce orders yet.<br><small>Once the storefront is connected, customer orders will arrive here.</small></td></tr><?php endif; ?></tbody></table></div></div><div class="mt-3"><?php echo e($orders->links()); ?></div>
